using System.Buffers.Binary;
using System.IO.Compression;

namespace Nightware.Application.Tests.Directory;

/// <summary>Real image bytes for the photo tests.</summary>
internal static class TestImages
{
    /// <summary>An 8x8 JPEG (made with sips; the capture tool's contact photo).</summary>
    public static byte[] Jpeg8 { get; } = Convert.FromBase64String("");

    /// <summary>A valid RGBA PNG of the given size.</summary>
    public static byte[] Png(int width, int height)
    {
        using var output = new MemoryStream();
        output.Write([0x89, 0x50, 0x4E, 0x47, 0x0D, 0x0A, 0x1A, 0x0A]);
        var header = new byte[13];
        BinaryPrimitives.WriteInt32BigEndian(header, width);
        BinaryPrimitives.WriteInt32BigEndian(header.AsSpan(4), height);
        header[8] = 8;
        header[9] = 6;
        Chunk(output, "IHDR"u8, header);
        using (var raw = new MemoryStream())
        {
            using (var z = new ZLibStream(raw, CompressionLevel.Fastest, leaveOpen: true))
            {
                for (var y = 0; y < height; y++)
                {
                    z.Write(new byte[1 + (width * 4)]);
                }
            }

            Chunk(output, "IDAT"u8, raw.ToArray());
        }

        Chunk(output, "IEND"u8, []);
        return output.ToArray();
    }

    private static void Chunk(Stream output, ReadOnlySpan<byte> type, byte[] data)
    {
        Span<byte> length = stackalloc byte[4];
        BinaryPrimitives.WriteInt32BigEndian(length, data.Length);
        output.Write(length);
        output.Write(type);
        output.Write(data);
        output.Write([0, 0, 0, 0]); // the CRC isn't read by anything under test
    }
}
